const lead = $input.item.json;

// Sin teléfono válido
if (!lead['número_de_teléfono'] || String(lead['número_de_teléfono']) === '') return [];

// Estados ya resueltos — no tocar
const estadosFinales = ['MQL', 'NURTURING', 'COMPLETADO', 'NO_CALIFICA'];
if (estadosFinales.includes(String(lead.mql_result))) return [];
if (estadosFinales.includes(String(lead.wa_estado)))  return [];

// Lead activo respondiendo en este momento — no interrumpir
if (String(lead.wa_estado) === 'EN_PROCESO') return [];

// Fecha de referencia: wa_last_contact → fallback created_time
const fechaRef =
  (lead.wa_last_contact && String(lead.wa_last_contact).trim() !== '')
    ? lead.wa_last_contact
    : (lead.created_time && String(lead.created_time).trim() !== '')
      ? lead.created_time
      : null;

if (!fechaRef) return [];

// Tiempo transcurrido desde el último contacto o creación
const horasTranscurridas = (Date.now() - new Date(fechaRef).getTime()) / (1000 * 60 * 60);
const intentos           = parseInt(lead.wa_attempt || 0);

// Tiempos mínimos por intento
// attempt=0 → 24h → RC1 | attempt=1 → 48h → RC2 | attempt=2 → 72h → RC3
const tiemposEspera   = [24, 48, 72];
const tiempoNecesario = tiemposEspera[intentos] ?? 999;

if (intentos >= 3)                        return []; // Agotó los 3 intentos
if (horasTranscurridas < tiempoNecesario) return []; // Aún no es tiempo

// ✅ String para que el Switch compare sin error de tipo
const tipoRecontacto = String(intentos + 1);

return [{
  json: {
    ...lead,
    tipoRecontacto,
    horasTranscurridas: Math.round(horasTranscurridas)
  }
}];

// RE-CONTACTO 1 (24h): No respondió al mensaje inicial
const lead = $input.item.json;
const nombre = lead.nombre_completo?.split(' ')[0] || '';
const rutas = lead['tamaño_de_operación'] || 'varias';
const dolor = lead.mayor_dolor || 'tu operación';

const mensaje = `Hola ${nombre}, te escribo nuevamente 👋

Vi que cuentas con *${rutas}* activas y querías evaluar cómo mejorar *${dolor}* en tu operación.

Podemos darte un diagnóstico claro en pocos minutos.

¿Te parece si retomamos?

✅ *SI* / ❌ *NO*`;

return [{ json: { ...lead, message: mensaje, tipoRecontactoLabel: 'Recontacto 1 (24h)' } }];

// RE-CONTACTO 2 (48h): Sigue sin responder
const lead = $input.item.json;
const nombre = lead.nombre_completo?.split(' ')[0] || '';
const rutas = lead['tamaño_de_operación'] || 'varias';
const dolor = lead.mayor_dolor || 'la operación';

const mensaje = `${nombre}, una consulta rápida 🤔

Empresas con *${rutas}* rutas como la tuya suelen tener problemas en *${dolor}*, afectando su operación y productividad.

Estamos ayudando a detectarlo en menos de 5 minutos.

¿Quieres que revisemos tu caso?`;

return [{ json: { ...lead, message: mensaje, tipoRecontactoLabel: 'Recontacto 2 (48h)' } }];

// RE-CONTACTO 3 (72h): Último intento
const lead = $input.item.json;
const nombre = lead.nombre_completo?.split(' ')[0] || '';

const mensaje = `Hola ${nombre}, cierro este contacto por ahora 👋

Si en algún momento quieres entender cómo mejorar tu operación, puedes escribirnos aquí directamente.

Si en este momento no es prioridad, no hay problema, solo dime y dejamos de contactarte.`;

return [{ json: { ...lead, message: mensaje, tipoRecontactoLabel: 'Recontacto 3 - Cierre (72h)' } }];

const lead    = $input.item.json;
const nombre  = lead.nombre_completo?.split(' ')[0] || '';
const intentos = parseInt(lead.wa_attempt || 0);

// intento 0 → mensaje 1h  | intento 1 → mensaje 24h
const mensaje = intentos === 0
  ? `Hola ${nombre}, quedamos a medio registro 👀\n\nNos faltan unos datos por completar.\n\n¿Continuamos?`
  : `Seguimos pendientes con tu registro 🚀\n\nCompletarlo te toma menos de 2 minutos.\n\n¿Te ayudo a terminarlo?`;

return [{ json: { ...lead, message: mensaje, tipoRecontactoLabel: 'Recontacto Abandono' } }];

// Evalúa si el lead pasa a Nurturing frío (3 intentos sin respuesta)
const lead = $input.item.json;
const intentosActuales = parseInt(lead.wa_attempt || 0) + 1;
const pasaANurturing   = intentosActuales >= 4; // RC1+RC2+RC3 = 3 intentos reales

// ── GMT-5 timestamp ───────────────────────────────────────────────
function toGMTMinus5() {
  const local = new Date(Date.now() + (-5 * 60 * 60 * 1000));
  const yyyy  = local.getUTCFullYear();
  const MM    = String(local.getUTCMonth() + 1).padStart(2, '0');
  const dd    = String(local.getUTCDate()).padStart(2, '0');
  const hh    = String(local.getUTCHours()).padStart(2, '0');
  const mm    = String(local.getUTCMinutes()).padStart(2, '0');
  const ss    = String(local.getUTCSeconds()).padStart(2, '0');
  return `${yyyy}-${MM}-${dd} ${hh}:${mm}:${ss}`;
}

const ahora = toGMTMinus5();

// ── Asigna la fecha al campo recontacto correcto según intento ────
// intentosActuales=1 → recontacto_1_fecha
// intentosActuales=2 → recontacto_2_fecha
// intentosActuales=3 → recontacto_3_fecha
const recontacto_1_fecha = intentosActuales === 1 ? ahora : (lead.recontacto_1_fecha || '');
const recontacto_2_fecha = intentosActuales === 2 ? ahora : (lead.recontacto_2_fecha || '');
const recontacto_3_fecha = intentosActuales === 3 ? ahora : (lead.recontacto_3_fecha || '');

return [{
  json: {
    ...lead,
    wa_attempt_nuevo:    intentosActuales,
    wa_estado_nuevo:     pasaANurturing ? 'NURTURING'           : 'ESPERANDO_RESPUESTA',
    mql_result_nuevo:    pasaANurturing ? 'NURTURING'           : lead.mql_result,
    lead_status_nuevo:   pasaANurturing ? 'NURTURING_FRIO'      : 'EN_VALIDACION',
    wa_last_contact_nuevo: ahora,          // ✅ siempre actualiza con timestamp actual
    recontacto_1_fecha,                    // ✅ fecha del RC1 si fue el primer intento
    recontacto_2_fecha,                    // ✅ fecha del RC2 si fue el segundo intento
    recontacto_3_fecha,                    // ✅ fecha del RC3 si fue el tercer intento
    pasaANurturing
  }
}];

