  const match = texto.match(
    /^(\d{4})-(\d{2})-(\d{2})(?:[ T](\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?$/
  );

  if (!match) {
    const fallback = new Date(texto.replace(' ', 'T') + '+00:00');
    const fallbackUTC = new Date(fallback.getTime() + 5 * 60 * 60 * 1000);
    return isNaN(fallbackUTC.getTime()) ? null : fallbackUTC;
  }

  const year   = Number(match[1]);
  const month  = Number(match[2]);
  const day    = Number(match[3]);
  const hour   = Number(match[4] ?? 0);
  const minute = Number(match[5] ?? 0);
  const second = Number(match[6] ?? 0);

  return new Date(Date.UTC(year, month - 1, day, hour + 5, minute, second));
}

function formatFechaEC(date) {
  const msEC = date.getTime() - 5 * 60 * 60 * 1000;
  const d = new Date(msEC);
  const pad = n => String(n).padStart(2, '0');
  return `${d.getUTCFullYear()}-${pad(d.getUTCMonth()+1)}-${pad(d.getUTCDate())} ${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}:${pad(d.getUTCSeconds())}`;
}

const ahora = new Date();
const VENTANA_HORAS = 23;

for (const item of items) {
  const lead = item.json;
  const waEstado = String(lead.wa_estado || '').trim().toUpperCase();

  if (waEstado !== 'PENDIENTE') continue;

  const createdTime = parseFechaEC(lead.created_time);
  if (!createdTime) continue;

  const r1Date = parseFechaEC(lead.recontacto_1_fecha);
  const r2Date = parseFechaEC(lead.recontacto_2_fecha);
  const r3Date = parseFechaEC(lead.recontacto_3_fecha);
  const r4Date = parseFechaEC(lead.recontacto_4_fecha);

  const r1Hecho = !!r1Date;
  const r2Hecho = !!r2Date;
  const r3Hecho = !!r3Date;
  const r4Hecho = !!r4Date;

  const waLastContact = parseFechaEC(lead.wa_last_contact);
  const baseParaR1 = waLastContact || createdTime;
  const baseParaR2 = r1Date;
  const baseParaR3 = r2Date;
  const baseParaR4 = r3Date;

  let tipoRecontacto = '';
  let tipoRecontactoLabel = '';
  let campoFechaActualizar = '';
  let baseUsada = null;

  if (!r1Hecho && baseParaR1) {
    const horas = (ahora - baseParaR1) / 3600000;
    if (horas >= VENTANA_HORAS) {
      tipoRecontacto = '1';
      tipoRecontactoLabel = 'Recontacto 1 (23h)';
      campoFechaActualizar = 'recontacto_1_fecha';
      baseUsada = baseParaR1;
    }
  } else if (r1Hecho && !r2Hecho && baseParaR2) {
    const horas = (ahora - baseParaR2) / 3600000;
    if (horas >= VENTANA_HORAS) {
      tipoRecontacto = '2';
      tipoRecontactoLabel = 'Recontacto 2 (23h)';
      campoFechaActualizar = 'recontacto_2_fecha';
      baseUsada = baseParaR2;
    }
  } else if (r2Hecho && !r3Hecho && baseParaR3) {
    const horas = (ahora - baseParaR3) / 3600000;
    if (horas >= VENTANA_HORAS) {
      tipoRecontacto = '3';
      tipoRecontactoLabel = 'Recontacto 3 (23h)';
      campoFechaActualizar = 'recontacto_3_fecha';
      baseUsada = baseParaR3;
    }
  } else if (r3Hecho && !r4Hecho && baseParaR4) {
    const horas = (ahora - baseParaR4) / 3600000;
    if (horas >= VENTANA_HORAS) {
      tipoRecontacto = '4';
      tipoRecontactoLabel = 'Recontacto 4 (23h)';
      campoFechaActualizar = 'recontacto_4_fecha';
      baseUsada = baseParaR4;
    }
  }

  if (!tipoRecontacto) {
    if (DEBUG) {
      let sigBase = null;
      let sigNum = '';
      if (!r1Hecho)      { sigBase = baseParaR1; sigNum = '1'; }
      else if (!r2Hecho) { sigBase = baseParaR2; sigNum = '2'; }
      else if (!r3Hecho) { sigBase = baseParaR3; sigNum = '3'; }
      else if (!r4Hecho) { sigBase = baseParaR4; sigNum = '4'; }

      const horasTranscurridas = sigBase ? (ahora - sigBase) / 3600000 : 0;
      const horasFaltantes     = sigBase ? Math.max(0, VENTANA_HORAS - horasTranscurridas) : 0;
      const proximoEnvio       = sigBase
        ? formatFechaEC(new Date(sigBase.getTime() + VENTANA_HORAS * 3600000))
        : '';

      salida.push({
        json: {
          ...lead,
          pasaFiltro: false,
          siguienteRecontacto: sigNum,
          horasTranscurridas: Number(horasTranscurridas.toFixed(2)),
          horasFaltantes: Number(horasFaltantes.toFixed(2)),
          proximoEnvio,
          motivoFiltro: sigNum
            ? `Todavía no corresponde Recontacto ${sigNum} — faltan ${horasFaltantes.toFixed(1)}h`
            : 'Ya tiene los 4 recontactos realizados'
        }
      });
    }
    continue;
  }

  salida.push({
    json: {
      ...lead,
      tipoRecontacto,
      tipoRecontactoLabel,
      campoFechaActualizar,
      pasaFiltro: true,
      horasRequeridas: VENTANA_HORAS,
      proximoEnvioCalculado: formatFechaEC(
        new Date(baseUsada.getTime() + VENTANA_HORAS * 3600000)
      ),
      motivoFiltro: `Lead pendiente listo para ${tipoRecontactoLabel}`
    }
  });
}

return salida;

