function parseFechaEC(valor) {
  if (valor === null || valor === undefined) return null;
  const texto = String(valor).trim();
  if (!texto) return null;

  // ✅ Acepta 1 o 2 dígitos en hora, minuto y segundo
  const match = texto.match(
    /^(\d{4})-(\d{2})-(\d{2})(?:[ T](\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?$/
  );

  if (!match) {
    const fallback = new Date(texto.replace(' ', 'T') + '+00:00');
    const fallbackUTC = new Date(fallback.getTime() + 5 * 60 * 60 * 1000);
    return isNaN(fallbackUTC.getTime()) ? null : fallbackUTC;
  }

  const year   = Number(match[1]);
  const month  = Number(match[2]);
  const day    = Number(match[3]);
  const hour   = Number(match[4] ?? 0);
  const minute = Number(match[5] ?? 0);
  const second = Number(match[6] ?? 0);

  return new Date(Date.UTC(year, month - 1, day, hour + 5, minute, second));
}

function formatFechaEC(date) {
  const msEC = date.getTime() - 5 * 60 * 60 * 1000;
  const d = new Date(msEC);
  const pad = n => String(n).padStart(2, '0');
  return `${d.getUTCFullYear()}-${pad(d.getUTCMonth()+1)}-${pad(d.getUTCDate())} ${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}:${pad(d.getUTCSeconds())}`;
}

